def with_degradation(name, primary, fallback, detector, *, critical=True):
    if detector.open(name):
        if critical:
            raise Unavailable(name)          # fail closed where it matters
        return mark_degraded(fallback(), name)
    try:
        return primary()
    except DependencyFailure as exc:
        detector.record(name, exc)
        if critical:
            raise
        return mark_degraded(fallback(), name)
